// Helper to construct concise, grammatically accurate lexicon entries
export function entry(
  arabic,
  transliteration,
  meaningTr,
  meaningFr,
  partOfSpeech,
  root,
  sarf,
  irab,
  derivatives,
  extra = {}
) {
  return {
    arabic,
    transliteration,
    meaningTr,
    meaningFr,
    partOfSpeech,
    root,
    sarf: {
      root,
      pattern: sarf[0],
      tense: sarf[1],
      number: sarf[2],
      gender: sarf[3],
    },
    irab: {
      role: irab[0],
      caseState: irab[1],
      reason: irab[2],
    },
    derivatives: derivatives.map(([ar, tr, fr]) => ({ ar, tr, fr })),
    ...extra,
  };
}

